-- =============================================================================
-- SEED DATA: 60 INTERVIEW QUESTIONS (LENGKAP 6 BIDANG x 10 SOAL)
-- =============================================================================

INSERT INTO interview_questions (id, job_field_id, question_number, category, question_text, sample_candidate_answer, ai_coach_tip, default_score, default_pacing_wpm, default_hesitation_rate, video_url) VALUES (101, 'admin', 1, 'Perkenalan Diri & Motivasi', 'Halo {name}, selamat pagi! Ceritakan sedikit tentang latar belakang pendidikan dan ketertarikanmu pada posisi Administrasi & Operasional ini.', 'Selamat pagi Bu Jessica. Saya memiliki latar belakang pendidikan Administrasi Bisnis dengan pengalaman menangani korespondensi, pengelolaan database operasional, dan pengarsipan digital. Saya tertarik pada posisi ini karena saya menikmati menciptakan alur kerja kantor yang rapi, terstruktur, dan efisien.', 'Gunakan struktur Elevator Pitch: latar belakang pendidikan, 1 keahlian utama dalam administrasi, dan alasan kuat memilih perusahaan ini.', 88, 134, '2%', '/Admin1.mp4') ON CONFLICT (id) DO UPDATE SET question_text = EXCLUDED.question_text, sample_candidate_answer = EXCLUDED.sample_candidate_answer, ai_coach_tip = EXCLUDED.ai_coach_tip;
INSERT INTO interview_questions (id, job_field_id, question_number, category, question_text, sample_candidate_answer, ai_coach_tip, default_score, default_pacing_wpm, default_hesitation_rate, video_url) VALUES (102, 'admin', 2, 'Keterampilan Software & Tools Kantor', 'Software perkantoran atau tools administrasi apa yang paling Anda kuasai (misalnya Microsoft Office, Google Workspace, atau sistem arsip) dan bagaimana penggunaannya?', 'Saya sangat terbiasa menggunakan Microsoft Excel tingkat menengah (VLOOKUP, IF bertingkat, Pivot Table untuk rekapitulasi data), Google Docs & Sheets untuk kolaborasi real-time, serta sistem pengarsipan cloud dengan standarisasi kode folder.', 'Sebutkan tools spesifik beserta fungsi fitur yang sering Anda gunakan dan estimasi volume dokumen yang pernah Anda kelola.', 86, 130, '3%', '/Admin2.mp4') ON CONFLICT (id) DO UPDATE SET question_text = EXCLUDED.question_text, sample_candidate_answer = EXCLUDED.sample_candidate_answer, ai_coach_tip = EXCLUDED.ai_coach_tip;
INSERT INTO interview_questions (id, job_field_id, question_number, category, question_text, sample_candidate_answer, ai_coach_tip, default_score, default_pacing_wpm, default_hesitation_rate, video_url) VALUES (103, 'admin', 3, 'Akurasi & Manajemen Data', 'Bagaimana metode Anda dalam memastikan akurasi data 100% saat harus menginput ratusan berkas atau formulir dalam tenggat waktu yang sangat ketat?', 'Saya menerapkan metode double-check bertahap: membagi input dalam batch per 50 berkas, menggunakan formula validasi data di spreadsheet untuk mencegah typo, serta melakukan rekonsiliasi silang antara dokumen fisik dan softcopy sebelum penyerahan final.', 'Jelaskan teknik pencegahan human-error (misal: data validation, checklist ganda, atau batch checking).', 85, 136, '2%', '/Admin3.mp4') ON CONFLICT (id) DO UPDATE SET question_text = EXCLUDED.question_text, sample_candidate_answer = EXCLUDED.sample_candidate_answer, ai_coach_tip = EXCLUDED.ai_coach_tip;
INSERT INTO interview_questions (id, job_field_id, question_number, category, question_text, sample_candidate_answer, ai_coach_tip, default_score, default_pacing_wpm, default_hesitation_rate, video_url) VALUES (104, 'admin', 4, 'Pengarsipan & Tata Kelola Dokumen', 'Bagaimana Anda menyusun sistem pengarsipan dokumen fisik dan digital agar rapi, aman, dan mudah ditemukan kembali oleh tim lain sewaktu-waktu?', 'Untuk arsip digital, saya menerapkan standarisasi penamaan file berformat [Tahun-Bulan-Hari]_[Kategori]_[NamaDokumen] dengan hak akses berbasis divisi. Untuk fisik, saya menggunakan sistem kode warna label pada ordner dan buku kendali peminjaman.', 'Tunjukkan pemahaman tentang sistem indeks arsip, protokol pencarian cepat, serta pembatasan hak akses dokumen sensitif.', 89, 132, '2%', '/Admin4.mp4') ON CONFLICT (id) DO UPDATE SET question_text = EXCLUDED.question_text, sample_candidate_answer = EXCLUDED.sample_candidate_answer, ai_coach_tip = EXCLUDED.ai_coach_tip;
INSERT INTO interview_questions (id, job_field_id, question_number, category, question_text, sample_candidate_answer, ai_coach_tip, default_score, default_pacing_wpm, default_hesitation_rate, video_url) VALUES (105, 'admin', 5, 'Manajemen Prioritas & Multitasking', 'Jika dalam waktu bersamaan Anda diminta merekap laporan harian, mengatur jadwal rapat mendesak pimpinan, dan memproses reimbursement, bagaimana Anda memprioritaskannya?', 'Saya mengelompokkan tugas berdasarkan matriks urgensi. Pertama, saya amankan jadwal rapat mendesak karena melibatkan stakeholder eksternal. Kedua, memproses reimbursement ke finance sebelum cut-off harian. Ketiga, menuntaskan rekap laporan operasional dengan tetap memantau timeline.', 'Gunakan metode Eisenhower Matrix (Penting vs Mendesak) dan komunikasikan ekspektasi waktu penyelesaian kepada atasan.', 87, 135, '3%', '/Admin5.mp4') ON CONFLICT (id) DO UPDATE SET question_text = EXCLUDED.question_text, sample_candidate_answer = EXCLUDED.sample_candidate_answer, ai_coach_tip = EXCLUDED.ai_coach_tip;
INSERT INTO interview_questions (id, job_field_id, question_number, category, question_text, sample_candidate_answer, ai_coach_tip, default_score, default_pacing_wpm, default_hesitation_rate, video_url) VALUES (106, 'admin', 6, 'Komunikasi & Kolaborasi Lintas Tim', 'Bagaimana cara Anda menindaklanjuti kelengkapan berkas operasional kepada divisi lain yang sering lambat merespons tanpa menimbulkan konflik antar-rekan kerja?', 'Saya menggunakan pendekatan diplomatis: mengirimkan reminder ramah via chat H-2 sebelum batas waktu dengan mencantumkan checklist berkas yang kurang, lalu menelepon langsung atau menghampiri rekan terkait jika mendekati tenggat untuk menawarkan bantuan bila ada kendala.', 'Fokus pada gaya komunikasi asertif namun solutif; tawarkan kemudahan daripada terkesan hanya menagih berkas.', 84, 131, '4%', '/Admin6.mp4') ON CONFLICT (id) DO UPDATE SET question_text = EXCLUDED.question_text, sample_candidate_answer = EXCLUDED.sample_candidate_answer, ai_coach_tip = EXCLUDED.ai_coach_tip;
INSERT INTO interview_questions (id, job_field_id, question_number, category, question_text, sample_candidate_answer, ai_coach_tip, default_score, default_pacing_wpm, default_hesitation_rate, video_url) VALUES (107, 'admin', 7, 'Problem Solving & Penanganan Berkas', 'Pernahkah Anda menghadapi situasi di mana dokumen penting mendadak terselip atau data rekapan tidak cocok? Langkah sistematis apa yang Anda ambil?', 'Saya tetap tenang, menelusuri riwayat tanda terima dan logbook mutasi dokumen terakhir, menghubungi person in charge yang terakhir meminjam, dan memeriksa salinan backup digital. Setelah teratasi, saya memperbarui buku ekspedisi agar insiden tidak terulang.', 'Jelaskan ketenangan dalam merespons krisis serta langkah perbaikan preventif pasca-insiden.', 83, 138, '3%', '/Admin7.mp4') ON CONFLICT (id) DO UPDATE SET question_text = EXCLUDED.question_text, sample_candidate_answer = EXCLUDED.sample_candidate_answer, ai_coach_tip = EXCLUDED.ai_coach_tip;
INSERT INTO interview_questions (id, job_field_id, question_number, category, question_text, sample_candidate_answer, ai_coach_tip, default_score, default_pacing_wpm, default_hesitation_rate, video_url) VALUES (108, 'admin', 8, 'Integritas & Kerahasiaan Perusahaan', 'Sebagai staf admin, Anda sering memegang dokumen rahasia seperti surat perjanjian kerja atau data kompensasi. Bagaimana Anda menjaga kerahasiaan informasi perusahaan?', 'Saya selalu mengunci folder cloud dengan izin otentikasi terbatas, menerapkan clean desk policy dengan tidak meninggalkan dokumen fisik di meja kerja, serta mematuhi perjanjian kerahasiaan (NDA) perusahaan dengan menolak membagikan data kepada pihak yang tidak berkepentingan.', 'Tegaskan komitmen terhadap etika kerahasiaan (Non-Disclosure) dan prinsip clean desk policy di lingkungan kantor.', 91, 129, '1%', '/Admin8.mp4') ON CONFLICT (id) DO UPDATE SET question_text = EXCLUDED.question_text, sample_candidate_answer = EXCLUDED.sample_candidate_answer, ai_coach_tip = EXCLUDED.ai_coach_tip;
INSERT INTO interview_questions (id, job_field_id, question_number, category, question_text, sample_candidate_answer, ai_coach_tip, default_score, default_pacing_wpm, default_hesitation_rate, video_url) VALUES (109, 'admin', 9, 'Inovasi & Efisiensi Alur Kerja', 'Apakah Anda pernah berinisiatif membuat template atau otomatisasi alur kerja baru yang berhasil mempercepat proses administrasi kantor? Ceritakan pengalaman tersebut.', 'Di pengalaman sebelumnya, pengajuan ATK masih memakai form kertas manual yang memakan waktu approval hingga 3 hari. Saya berinisiatif membuat form terintegrasi spreadsheet dengan notifikasi email otomatis, sehingga approval terpangkas menjadi hanya 4 jam.', 'Sebutkan metrik kuantitatif dampak inovasi Anda (misal: penghematan waktu approval dari 3 hari menjadi 4 jam atau penghematan kertas).', 92, 137, '2%', '/Admin9.mp4') ON CONFLICT (id) DO UPDATE SET question_text = EXCLUDED.question_text, sample_candidate_answer = EXCLUDED.sample_candidate_answer, ai_coach_tip = EXCLUDED.ai_coach_tip;
INSERT INTO interview_questions (id, job_field_id, question_number, category, question_text, sample_candidate_answer, ai_coach_tip, default_score, default_pacing_wpm, default_hesitation_rate, video_url) VALUES (110, 'admin', 10, 'Visi & Rencana Pengembangan Karir', 'Di mana Anda melihat diri Anda dalam 3 tahun ke depan di departemen Administrasi & Operasional perusahaan kami?', 'Dalam 3 tahun, saya ingin meningkatkan kompetensi menjadi Senior Administrative Officer atau Office Supervisor, memimpin digitalisasi seluruh alur administrasi kantor, serta menguasai sistem ERP perusahaan untuk mendukung efisiensi operasional secara berkelanjutan.', 'Tautkan ambisi pengembangan diri dengan kontribusi jangka panjang bagi stabilitas dan kemajuan operasional perusahaan.', 90, 133, '2%', '/Admin10.mp4') ON CONFLICT (id) DO UPDATE SET question_text = EXCLUDED.question_text, sample_candidate_answer = EXCLUDED.sample_candidate_answer, ai_coach_tip = EXCLUDED.ai_coach_tip;
INSERT INTO interview_questions (id, job_field_id, question_number, category, question_text, sample_candidate_answer, ai_coach_tip, default_score, default_pacing_wpm, default_hesitation_rate, video_url) VALUES (201, 'accounting', 1, 'Perkenalan Diri & Motivasi', 'Halo {name}, selamat pagi! Ceritakan sedikit tentang latar belakang pendidikan dan ketertarikanmu pada posisi Accounting ini.', 'Selamat pagi Bu Jessica. Saya lulusan S1 Akuntansi dengan pengalaman magang 6 bulan di firma auditor. Saya terbiasa mengelola cash flow, buku besar, dan ingin mengembangkan karir di industri ini.', 'Buka dengan elevator pitch 60 detik: latar belakang pendidikan, 1 pencapaian utama, dan benang merah ke visi perusahaan.', 90, 135, '2%', '/Accounting1.mp4') ON CONFLICT (id) DO UPDATE SET question_text = EXCLUDED.question_text, sample_candidate_answer = EXCLUDED.sample_candidate_answer, ai_coach_tip = EXCLUDED.ai_coach_tip;
INSERT INTO interview_questions (id, job_field_id, question_number, category, question_text, sample_candidate_answer, ai_coach_tip, default_score, default_pacing_wpm, default_hesitation_rate, video_url) VALUES (202, 'accounting', 2, 'Penguasaan Konsep Teknis', 'Bagaimana pemahaman Anda mengenai siklus pencatatan akun beban akrual dan penyesuaiannya di akhir periode pembukuan?', 'Tentu Bu. Beban akrual dicatat saat biaya telah terjadi meskipun kas belum dikeluarkan, menggunakan prinsip matching principle agar laporan laba rugi mencerminkan kondisi riil.', 'Sebutkan contoh akun riil seperti beban listrik atau gaji terutang beserta ayat jurnal debit-kreditnya.', 85, 130, '3%', '/Accounting2.mp4') ON CONFLICT (id) DO UPDATE SET question_text = EXCLUDED.question_text, sample_candidate_answer = EXCLUDED.sample_candidate_answer, ai_coach_tip = EXCLUDED.ai_coach_tip;
INSERT INTO interview_questions (id, job_field_id, question_number, category, question_text, sample_candidate_answer, ai_coach_tip, default_score, default_pacing_wpm, default_hesitation_rate, video_url) VALUES (203, 'accounting', 3, 'Closing & Audit / Problem Solving', 'Ketika menemukan selisih saldo di jurnal penyesuaian yang belum teridentifikasi menjelang closing audit bulanan, langkah sistematis apa yang kamu ambil untuk menelusurinya?', 'Pertama, saya akan melakukan audit trail mundur pada transaksi periode terkait, memeriksa error transposition pada buku besar, lalu mencocokkan mutasi rekening koran dengan rekonsiliasi 3-way match sebelum mengajukan jurnal koreksi.', 'Jelaskan secara spesifik metodologi Action Anda (misal: teknik cross-check ledger, formula excel, atau komunikasi dengan tim treasury).', 75, 138, '5%', '/Accounting3.mp4') ON CONFLICT (id) DO UPDATE SET question_text = EXCLUDED.question_text, sample_candidate_answer = EXCLUDED.sample_candidate_answer, ai_coach_tip = EXCLUDED.ai_coach_tip;
INSERT INTO interview_questions (id, job_field_id, question_number, category, question_text, sample_candidate_answer, ai_coach_tip, default_score, default_pacing_wpm, default_hesitation_rate, video_url) VALUES (204, 'accounting', 4, 'Manajemen Prioritas & Pajak', 'Bagaimana Anda menyikapi tenggat waktu laporan pajak PPh 21/23 yang berdekatan dengan closing kas dan bank perusahaan?', 'Saya membuat time blocking matrix kuadran Eisenhower: draft bukti potong PPh disiapkan H-3 sebelum tanggal 10, sehingga H-1 saya fokus penuh pada closing rekonsiliasi kas.', 'Soroti mitigasi risiko denda keterlambatan e-Billing DJP dan tools otomatisasi spreadsheet yang Anda manfaatkan.', 88, 140, '3%', '/Accounting4.mp4') ON CONFLICT (id) DO UPDATE SET question_text = EXCLUDED.question_text, sample_candidate_answer = EXCLUDED.sample_candidate_answer, ai_coach_tip = EXCLUDED.ai_coach_tip;
INSERT INTO interview_questions (id, job_field_id, question_number, category, question_text, sample_candidate_answer, ai_coach_tip, default_score, default_pacing_wpm, default_hesitation_rate, video_url) VALUES (205, 'accounting', 5, 'Technical Skills & Software', 'Tools ERP atau spreadsheet akuntansi apa yang paling Anda kuasai dan seberapa jauh level kemahiran Anda dalam mengolah transaksi keuangan?', 'Saya mahir SAP modul FI/CO untuk entry jurnal dan posting aset tetap, serta mahir fungsi lanjutan Excel seperti XLOOKUP, Pivot Table, Index-Match, dan macro dasar otomatisasi rekonsiliasi.', 'Berikan estimasi volume data yang pernah Anda proses (misal: 1.500 baris transaksi per hari).', 83, 136, '4%', '/Accounting5.mp4') ON CONFLICT (id) DO UPDATE SET question_text = EXCLUDED.question_text, sample_candidate_answer = EXCLUDED.sample_candidate_answer, ai_coach_tip = EXCLUDED.ai_coach_tip;
INSERT INTO interview_questions (id, job_field_id, question_number, category, question_text, sample_candidate_answer, ai_coach_tip, default_score, default_pacing_wpm, default_hesitation_rate, video_url) VALUES (206, 'accounting', 6, 'Kolaborasi Lintas Divisi', 'Bagaimana cara Anda menagih kelengkapan nota expense claim kepada tim lapangan yang sering terlambat menyerahkan bukti fisik transaksi?', 'Saya membangun komunikasi persuasif dengan menyediakan form reimbursement digital dengan SLA jelas, serta memberikan notifikasi ramah H-2 cut-off agar reimbursement tidak tertunda.', 'Tunjukkan empati tanpa mengorbankan kepatuhan SOP audit kepatuhan keuangan.', 86, 132, '2%', '/Accounting6.mp4') ON CONFLICT (id) DO UPDATE SET question_text = EXCLUDED.question_text, sample_candidate_answer = EXCLUDED.sample_candidate_answer, ai_coach_tip = EXCLUDED.ai_coach_tip;
INSERT INTO interview_questions (id, job_field_id, question_number, category, question_text, sample_candidate_answer, ai_coach_tip, default_score, default_pacing_wpm, default_hesitation_rate, video_url) VALUES (207, 'accounting', 7, 'Integritas & Etika Profesi', 'Pernahkah Anda diminta atasan atau rekan kerja untuk membebankan pengeluaran non-bisnis ke pos operasional? Bagaimana sikap dan penyelesaian Anda?', 'Saya akan mengonfirmasi dengan sopan dasar pencatatannya mengacu pada PSAK dan kebijakan compliance perusahaan, serta menawarkan alternatif penanganan akun penampung yang sah dan transparan.', 'Tegaskan komitmen terhadap integritas akuntansi dengan komunikasi asertif tanpa nada menuduh.', 89, 128, '2%', '/Accounting7.mp4') ON CONFLICT (id) DO UPDATE SET question_text = EXCLUDED.question_text, sample_candidate_answer = EXCLUDED.sample_candidate_answer, ai_coach_tip = EXCLUDED.ai_coach_tip;
INSERT INTO interview_questions (id, job_field_id, question_number, category, question_text, sample_candidate_answer, ai_coach_tip, default_score, default_pacing_wpm, default_hesitation_rate, video_url) VALUES (208, 'accounting', 8, 'Penanganan Tekanan & Stres', 'Bagaimana strategi Anda menjaga konsentrasi dan akurasi entri transaksi saat beban kerja melonjak drastis di akhir tahun buku (closing tahunan)?', 'Saya membagi batch verifikasi per 50 voucher transaksi dengan check-and-balance rekonsiliasi silang dan istirahat mata 5 menit setiap 2 jam untuk mempertahankan fokus 100%.', 'Fokus pada strategi sistematis dan teknik verifikasi ganda (double-entry verification).', 84, 134, '3%', '/Accounting8.mp4') ON CONFLICT (id) DO UPDATE SET question_text = EXCLUDED.question_text, sample_candidate_answer = EXCLUDED.sample_candidate_answer, ai_coach_tip = EXCLUDED.ai_coach_tip;
INSERT INTO interview_questions (id, job_field_id, question_number, category, question_text, sample_candidate_answer, ai_coach_tip, default_score, default_pacing_wpm, default_hesitation_rate, video_url) VALUES (209, 'accounting', 9, 'Ketangkasan Belajar Regulasi', 'Bagaimana cara Anda terus memperbarui pemahaman terhadap peraturan perpajakan terbaru di Indonesia seperti integrasi NIK-NPWP atau tarif TER PPh 21?', 'Saya aktif mengikuti newsletter resmi Ditjen Pajak, webinar Ikatan Akuntan Indonesia (IAI), dan berdiskusi di forum komunitas profesional pajak.', 'Sebutkan contoh regulasi terkini seperti NIK jadi NPWP atau aturan tarif efektif rata-rata (TER) PPh 21.', 87, 136, '2%', '/Accounting9.mp4') ON CONFLICT (id) DO UPDATE SET question_text = EXCLUDED.question_text, sample_candidate_answer = EXCLUDED.sample_candidate_answer, ai_coach_tip = EXCLUDED.ai_coach_tip;
INSERT INTO interview_questions (id, job_field_id, question_number, category, question_text, sample_candidate_answer, ai_coach_tip, default_score, default_pacing_wpm, default_hesitation_rate, video_url) VALUES (210, 'accounting', 10, 'Ekspektasi Jenjang Karir', 'Di mana Anda melihat diri Anda dalam 3 tahun ke depan di departemen Accounting perusahaan kami?', 'Dalam 3 tahun ke depan, saya menargetkan untuk memegang sertifikasi Brevet AB dan CA, serta dipercaya memimpin sub-tim GL (General Ledger) untuk mengoptimalkan otomatisasi pelaporan keuangan.', 'Hubungkan aspirasi pertumbuhan profesional pribadi dengan kontribusi nyata terhadap efisiensi tim perusahaan.', 91, 137, '1%', '/Accounting10.mp4') ON CONFLICT (id) DO UPDATE SET question_text = EXCLUDED.question_text, sample_candidate_answer = EXCLUDED.sample_candidate_answer, ai_coach_tip = EXCLUDED.ai_coach_tip;
INSERT INTO interview_questions (id, job_field_id, question_number, category, question_text, sample_candidate_answer, ai_coach_tip, default_score, default_pacing_wpm, default_hesitation_rate, video_url) VALUES (301, 'finance', 1, 'Perkenalan Diri & Motivasi', 'Halo {name}, selamat pagi! Ceritakan sedikit tentang latar belakang pendidikan dan ketertarikanmu pada posisi Finance Analyst & Treasury ini.', 'Selamat pagi Bu Jessica. Saya memiliki latar belakang pendidikan S1 Manajemen Keuangan dengan pengalaman magang di bagian corporate treasury. Saya memiliki ketertarikan mendalam pada analisis kelayakan finansial, pemodelan keuangan (financial modeling), dan manajemen likuiditas kas perusahaan untuk mendukung keputusan bisnis strategis.', 'Sampaikan kombinasi pemahaman analisa data keuangan, latar pendidikan, dan motivasi kontribusi terhadap pertumbuhan bisnis.', 89, 136, '2%', '/Finance1.mp4') ON CONFLICT (id) DO UPDATE SET question_text = EXCLUDED.question_text, sample_candidate_answer = EXCLUDED.sample_candidate_answer, ai_coach_tip = EXCLUDED.ai_coach_tip;
INSERT INTO interview_questions (id, job_field_id, question_number, category, question_text, sample_candidate_answer, ai_coach_tip, default_score, default_pacing_wpm, default_hesitation_rate, video_url) VALUES (302, 'finance', 2, 'Manajemen Arus Kas & Likuiditas', 'Bagaimana pendekatan Anda dalam menyusun proyeksi arus kas (cash flow forecasting) mingguan maupun bulanan untuk memastikan likuiditas perusahaan tetap aman?', 'Saya memetakan pola historis penagihan piutang (AR aging) dan jadwal komitmen pengeluaran operasional (AP payment schedule), menyusun skenario kas konservatif dan moderat, serta menetapkan batas minimum buffer kas harian untuk mencegah shortfall likuiditas.', 'Jelaskan metodologi direct vs indirect cash flow serta antisipasi fluktuasi siklus modal kerja.', 87, 132, '3%', '/Finance2.mp4') ON CONFLICT (id) DO UPDATE SET question_text = EXCLUDED.question_text, sample_candidate_answer = EXCLUDED.sample_candidate_answer, ai_coach_tip = EXCLUDED.ai_coach_tip;
INSERT INTO interview_questions (id, job_field_id, question_number, category, question_text, sample_candidate_answer, ai_coach_tip, default_score, default_pacing_wpm, default_hesitation_rate, video_url) VALUES (303, 'finance', 3, 'Analisis Kinerja & Rasio Keuangan', 'Metrik atau rasio keuangan apa saja (seperti EBITDA, Working Capital, atau Current Ratio) yang menjadi fokus utama Anda dalam menganalisis kesehatan keuangan unit bisnis?', 'Saya mengawasi Working Capital Cycle untuk efisiensi modal, EBITDA margin untuk profitabilitas operasional murni, dan Debt Service Coverage Ratio (DSCR) untuk memantau keamanan kewajiban utang perbankan.', 'Hubungkan rasio finansial dengan implikasi keputusan bisnis nyata (misalnya percepatan penagihan AR atau negosiasi termin vendor).', 88, 134, '2%', '/Finance3.mp4') ON CONFLICT (id) DO UPDATE SET question_text = EXCLUDED.question_text, sample_candidate_answer = EXCLUDED.sample_candidate_answer, ai_coach_tip = EXCLUDED.ai_coach_tip;
INSERT INTO interview_questions (id, job_field_id, question_number, category, question_text, sample_candidate_answer, ai_coach_tip, default_score, default_pacing_wpm, default_hesitation_rate, video_url) VALUES (304, 'finance', 4, 'Analisis Varians Anggaran (Budgeting)', 'Bagaimana cara Anda melakukan analisis varians (Variance Analysis) antara anggaran belanja modal/operasional dengan realisasi pengeluaran aktual?', 'Saya membandingkan pos anggaran menggunakan flexible budget model, mengidentifikasi akar penyebab deviasi lebih dari 5% baik dari sisi harga maupun volume penggunaan, lalu menyusun rekomendasi tindakan korektif bersama kepala departemen terkait.', 'Jelaskan batas toleransi deviasi (threshold) dan cara Anda menyampaikan temuan ke unit kerja secara solutif.', 86, 135, '3%', '/Finance4.mp4') ON CONFLICT (id) DO UPDATE SET question_text = EXCLUDED.question_text, sample_candidate_answer = EXCLUDED.sample_candidate_answer, ai_coach_tip = EXCLUDED.ai_coach_tip;
INSERT INTO interview_questions (id, job_field_id, question_number, category, question_text, sample_candidate_answer, ai_coach_tip, default_score, default_pacing_wpm, default_hesitation_rate, video_url) VALUES (305, 'finance', 5, 'Mitigasi Risiko Pasar & Valas', 'Jika perusahaan menghadapi risiko fluktuasi nilai tukar valuta asing atau kenaikan suku bunga pinjaman, mitigasi treasury apa yang biasa Anda rekomendasikan?', 'Untuk eksposur mata uang asing, saya menganalisis natural hedging terlebih dahulu dengan mencocokkan piutang dan utang valas sejenis, lalu mengusulkan instrumen forward contract jika eksposur bersih signifikan. Untuk suku bunga, kita dapat mengevaluasi restrukturisasi pinjaman ke fixed rate.', 'Tunjukkan pemahaman instrumen treasury konvensional seperti forward contract, spot matching, dan analisa sensitivitas kurs.', 85, 131, '3%', '/Finance5.mp4') ON CONFLICT (id) DO UPDATE SET question_text = EXCLUDED.question_text, sample_candidate_answer = EXCLUDED.sample_candidate_answer, ai_coach_tip = EXCLUDED.ai_coach_tip;
INSERT INTO interview_questions (id, job_field_id, question_number, category, question_text, sample_candidate_answer, ai_coach_tip, default_score, default_pacing_wpm, default_hesitation_rate, video_url) VALUES (306, 'finance', 6, 'Evaluasi Kelayakan Investasi (Capex)', 'Bagaimana Anda mengevaluasi kelayakan sebuah usulan proyek investasi modal (Capex) menggunakan metode seperti NPV, IRR, atau Payback Period?', 'Saya membangun financial model DCF (Discounted Cash Flow) dengan menetapkan WACC sebagai hurdle rate. Proyek dinilai layak jika NPV positif dan IRR melampaui biaya modal, lalu saya melengkapi analisis dengan skenario uji sensitivitas (best case, base case, worst case).', 'Soroti pentingnya discount rate (WACC) dan pengujian sensitivitas terhadap asumsi pendapatan serta biaya operasional.', 90, 137, '2%', '/Finance6.mp4') ON CONFLICT (id) DO UPDATE SET question_text = EXCLUDED.question_text, sample_candidate_answer = EXCLUDED.sample_candidate_answer, ai_coach_tip = EXCLUDED.ai_coach_tip;
INSERT INTO interview_questions (id, job_field_id, question_number, category, question_text, sample_candidate_answer, ai_coach_tip, default_score, default_pacing_wpm, default_hesitation_rate, video_url) VALUES (307, 'finance', 7, 'Hubungan Perbankan & Negosiasi Finansial', 'Ceritakan pengalaman Anda dalam bernegosiasi atau berkoordinasi dengan pihak perbankan mengenai penempatan dana deposito, fasilitas kredit, atau biaya transaksi bank.', 'Saya rutin melakukan tender bunga deposito antar beberapa bank mitra untuk mendapatkan yield kompetitif di atas rata-rata BI rate tanpa mengorbankan keamanan bank, serta berhasil menegosiasikan penurunan biaya transaksi massal hingga 15% untuk efisiensi kas keluar.', 'Berikan bukti negosiasi berbasis perbandingan data (benchmarking) yang menghasilkan penghematan biaya riil.', 88, 133, '2%', '/Finance7.mp4') ON CONFLICT (id) DO UPDATE SET question_text = EXCLUDED.question_text, sample_candidate_answer = EXCLUDED.sample_candidate_answer, ai_coach_tip = EXCLUDED.ai_coach_tip;
INSERT INTO interview_questions (id, job_field_id, question_number, category, question_text, sample_candidate_answer, ai_coach_tip, default_score, default_pacing_wpm, default_hesitation_rate, video_url) VALUES (308, 'finance', 8, 'Visualisasi Data & Komunikasi Eksekutif', 'Bagaimana Anda menyajikan visualisasi data keuangan yang rumit ke dalam dashboard ringkas agar mudah dipahami oleh jajaran direksi non-finance?', 'Saya menyederhanakan data angka menjadi visual dashboard dengan format traffic light (hijau-kuning-merah) untuk indikator KPI utama, menyoroti 3 poin insight kritis teratas, serta menyertakan rekomendasi aksi bagi keputusan bisnis tanpa membebani istilah teknis rumit.', 'Tekankan prinsip "Storytelling with Data": sajikan konteks, tantangan, dan rekomendasi aksi nyata.', 87, 138, '3%', '/Finance8.mp4') ON CONFLICT (id) DO UPDATE SET question_text = EXCLUDED.question_text, sample_candidate_answer = EXCLUDED.sample_candidate_answer, ai_coach_tip = EXCLUDED.ai_coach_tip;
INSERT INTO interview_questions (id, job_field_id, question_number, category, question_text, sample_candidate_answer, ai_coach_tip, default_score, default_pacing_wpm, default_hesitation_rate, video_url) VALUES (309, 'finance', 9, 'Efisiensi Biaya & Penanganan Kebocoran', 'Pernahkah Anda mengidentifikasi potensi kebocoran anggaran (cost overrun) dan langkah konkret apa yang Anda rekomendasikan untuk efisiensi?', 'Saat menganalisis akun biaya logistik, saya menemukan deviasi biaya keterlambatan kontainer akibat lambatnya clearance pelabuhan. Saya merekomendasikan revisi SOP jadwal clearance bersama tim supply chain yang sukses menghemat biaya operasional sebesar 80 juta rupiah per kuartal.', 'Gunakan metode STAR dengan angka kuantitatif spesifik atas penghematan atau perbaikan yang berhasil Anda ciptakan.', 92, 136, '2%', '/Finance9.mp4') ON CONFLICT (id) DO UPDATE SET question_text = EXCLUDED.question_text, sample_candidate_answer = EXCLUDED.sample_candidate_answer, ai_coach_tip = EXCLUDED.ai_coach_tip;
INSERT INTO interview_questions (id, job_field_id, question_number, category, question_text, sample_candidate_answer, ai_coach_tip, default_score, default_pacing_wpm, default_hesitation_rate, video_url) VALUES (310, 'finance', 10, 'Visi Karir & Pengembangan Profesional', 'Apa target pencapaian profesional dan sertifikasi yang ingin Anda raih dalam 3 tahun ke depan di bidang Finance perusahaan kami?', 'Dalam 3 tahun, saya menargetkan untuk menyelesaikan sertifikasi CFA atau Certified Treasury Professional (CTP), memimpin otomatisasi pelaporan FP&A, dan berkontribusi langsung dalam perencanaan strategi pendanaan ekspansi bisnis perusahaan.', 'Tunjukkan komitmen belajar berkelanjutan dan bagaimana keahlian yang Anda asah berdampak langsung pada nilai perusahaan.', 91, 135, '1%', '/Finance10.mp4') ON CONFLICT (id) DO UPDATE SET question_text = EXCLUDED.question_text, sample_candidate_answer = EXCLUDED.sample_candidate_answer, ai_coach_tip = EXCLUDED.ai_coach_tip;
INSERT INTO interview_questions (id, job_field_id, question_number, category, question_text, sample_candidate_answer, ai_coach_tip, default_score, default_pacing_wpm, default_hesitation_rate, video_url) VALUES (401, 'sales', 1, 'Perkenalan Diri & Motivasi', 'Halo {name}, selamat pagi! Ceritakan sedikit tentang latar belakang pengalaman dan ketertarikanmu pada posisi Sales & Marketing ini.', 'Selamat pagi Bu Jessica. Saya memiliki pengalaman 2 tahun di bidang B2B Business Development dan Sales lapangan. Saya memiliki passion dalam membangun relasi bisnis, memahami pain-point calon klien, dan memberikan solusi produk yang mampu melampaui target revenue perusahaan.', 'Awali dengan energi positif dan antusiasme tinggi; sebutkan pencapaian angka sales terbaik Anda di awal.', 90, 142, '2%', '/Sales1.mp4') ON CONFLICT (id) DO UPDATE SET question_text = EXCLUDED.question_text, sample_candidate_answer = EXCLUDED.sample_candidate_answer, ai_coach_tip = EXCLUDED.ai_coach_tip;
INSERT INTO interview_questions (id, job_field_id, question_number, category, question_text, sample_candidate_answer, ai_coach_tip, default_score, default_pacing_wpm, default_hesitation_rate, video_url) VALUES (402, 'sales', 2, 'Prospecting & Saluran Penjualan', 'Bagaimana strategi Anda dalam melakukan prospecting dan membangun saluran calon klien baru (sales pipeline) dari tahap awal hingga menjadi qualified leads?', 'Saya memadukan outbound prospecting melalui LinkedIn dan cold-calling dengan pendekatan konsultatif, memfilter prospek menggunakan kriteria BANT (Budget, Authority, Need, Timeline), serta memastikan rasio pipeline selalu 3x lipat dari target kuota bulanan saya.', 'Jelaskan kriteria kualifikasi leads (seperti BANT atau MEDDIC) dan disiplin menjaga rasio pipeline coverage.', 87, 138, '2%', '/Sales2.mp4') ON CONFLICT (id) DO UPDATE SET question_text = EXCLUDED.question_text, sample_candidate_answer = EXCLUDED.sample_candidate_answer, ai_coach_tip = EXCLUDED.ai_coach_tip;
INSERT INTO interview_questions (id, job_field_id, question_number, category, question_text, sample_candidate_answer, ai_coach_tip, default_score, default_pacing_wpm, default_hesitation_rate, video_url) VALUES (403, 'sales', 3, 'Handling Objection & Negosiasi', 'Ceritakan pengalaman Anda saat menghadapi penolakan keras (objection) dari calon klien yang membandingkan produk Anda dengan kompetitor yang jauh lebih murah.', 'Saya tidak langsung menurunkan harga atau meremehkan kompetitor, melainkan mendengarkan kekhawatiran mereka, lalu membedah Total Cost of Ownership (TCO) dan ROI nyata dari produk kami, seperti garansi SLA cepat, keandalan teknis, dan training purnajual yang tidak dimiliki kompetitor murah.', 'Tunjukkan teknik pergeseran fokus dari "Harga Satuan" ke "Nilai Tambah & ROI Jangka Panjang" (Value-based Selling).', 89, 136, '2%', '/Sales3.mp4') ON CONFLICT (id) DO UPDATE SET question_text = EXCLUDED.question_text, sample_candidate_answer = EXCLUDED.sample_candidate_answer, ai_coach_tip = EXCLUDED.ai_coach_tip;
INSERT INTO interview_questions (id, job_field_id, question_number, category, question_text, sample_candidate_answer, ai_coach_tip, default_score, default_pacing_wpm, default_hesitation_rate, video_url) VALUES (404, 'sales', 4, 'Pengelolaan Key Account & Retensi', 'Bagaimana teknik Anda dalam mengelola hubungan jangka panjang dengan akun-akun kunci (Key Accounts) agar terjadi repeat order dan peluang up-selling?', 'Saya menjadwalkan quarterly review rutin untuk mengevaluasi kepuasan mereka, menjadi penasihat terpercaya yang proaktif memberikan solusi saat tren industri mereka berubah, serta memanfaatkan momen tersebut untuk memperkenalkan paket add-on produk yang relevan.', 'Tekankan pentingnya relasi berbasis nilai keberlanjutan (trusted advisor) bukan sekadar transaksi satu kali.', 86, 134, '3%', '/Sales4.mp4') ON CONFLICT (id) DO UPDATE SET question_text = EXCLUDED.question_text, sample_candidate_answer = EXCLUDED.sample_candidate_answer, ai_coach_tip = EXCLUDED.ai_coach_tip;
INSERT INTO interview_questions (id, job_field_id, question_number, category, question_text, sample_candidate_answer, ai_coach_tip, default_score, default_pacing_wpm, default_hesitation_rate, video_url) VALUES (405, 'sales', 5, 'Tools CRM & Manajemen Aktivitas', 'Tools CRM apa (seperti HubSpot, Salesforce, atau pipeline spreadsheet) yang biasa Anda gunakan untuk memonitor progres deal dan funnel penjualan?', 'Saya sangat terbiasa menggunakan CRM untuk mencatat interaksi harian (call log, email thread, meeting notes), memantau pergerakan deal stage, menetapkan follow-up task otomatis, dan menganalisis win-loss ratio setiap bulan.', 'Jelaskan kedisiplinan Anda dalam meng-update data CRM sebagai dasar akurasi sales forecasting bagi manajemen.', 88, 135, '2%', '/Sales5.mp4') ON CONFLICT (id) DO UPDATE SET question_text = EXCLUDED.question_text, sample_candidate_answer = EXCLUDED.sample_candidate_answer, ai_coach_tip = EXCLUDED.ai_coach_tip;
INSERT INTO interview_questions (id, job_field_id, question_number, category, question_text, sample_candidate_answer, ai_coach_tip, default_score, default_pacing_wpm, default_hesitation_rate, video_url) VALUES (406, 'sales', 6, 'Sinergi Sales & Digital Marketing', 'Bagaimana cara Anda berkolaborasi dengan tim digital marketing agar lead yang didapat dari iklan online dapat segera dikonversi menjadi penjualan riil?', 'Saya memastikan SLA kontak awal (speed-to-lead) maksimal 15 menit setelah lead masuk, memberikan feedback mingguan kepada tim marketing terkait kualitas lead dan materi iklan mana yang menghasilkan closing tertinggi, sehingga anggaran marketing dialokasikan lebih efisien.', 'Soroti metrik "Speed to Lead" dan feedback loop berkala antara divisi marketing dan tim penjualan.', 85, 137, '3%', '/Sales6.mp4') ON CONFLICT (id) DO UPDATE SET question_text = EXCLUDED.question_text, sample_candidate_answer = EXCLUDED.sample_candidate_answer, ai_coach_tip = EXCLUDED.ai_coach_tip;
INSERT INTO interview_questions (id, job_field_id, question_number, category, question_text, sample_candidate_answer, ai_coach_tip, default_score, default_pacing_wpm, default_hesitation_rate, video_url) VALUES (407, 'sales', 7, 'Penanganan Target Darurat (Closer Mentality)', 'Ketika target omzet bulanan masih kurang 30% di minggu ketiga, taktik penjualan taktis apa yang Anda terapkan untuk mengejar target sebelum akhir bulan?', 'Saya melakukan triage pada pipeline: fokus 80% energi pada warm leads yang sudah di tahap proposal/negosiasi, menawarkan insentif terbatas seperti bundling layanan atau kemudahan termin pembayaran, serta mengontak pelanggan setia yang berpotensi melakukan repeat order lebih awal.', 'Tunjukkan ketangguhan mental under pressure dan strategi alokasi waktu berbasis probabilitas closing tertinggi.', 91, 140, '2%', '/Sales7.mp4') ON CONFLICT (id) DO UPDATE SET question_text = EXCLUDED.question_text, sample_candidate_answer = EXCLUDED.sample_candidate_answer, ai_coach_tip = EXCLUDED.ai_coach_tip;
INSERT INTO interview_questions (id, job_field_id, question_number, category, question_text, sample_candidate_answer, ai_coach_tip, default_score, default_pacing_wpm, default_hesitation_rate, video_url) VALUES (408, 'sales', 8, 'Pencapaian Terbaik (Success Story)', 'Ceritakan salah satu keberhasilan closing terbesar yang pernah Anda raih, berapa persentase target yang Anda lampaui, dan bagaimana strateginya?', 'Tahun lalu saya berhasil mengunci kontrak tahunan bernilai 450 juta rupiah dengan korporasi manufaktur, membuat saya mencapai 135% dari kuota kuartal. Kuncinya adalah pemetaan multi-stakeholder: mendekati user di divisi operasional sekaligus mempresentasikan efisiensi anggaran kepada direktur keuangan mereka.', 'Gunakan formula STAR lengkap: paparkan nominal transaksi, persentase pencapaian kuota, dan taktik multi-threading stakeholder.', 93, 139, '1%', '/Sales8.mp4') ON CONFLICT (id) DO UPDATE SET question_text = EXCLUDED.question_text, sample_candidate_answer = EXCLUDED.sample_candidate_answer, ai_coach_tip = EXCLUDED.ai_coach_tip;
INSERT INTO interview_questions (id, job_field_id, question_number, category, question_text, sample_candidate_answer, ai_coach_tip, default_score, default_pacing_wpm, default_hesitation_rate, video_url) VALUES (409, 'sales', 9, 'Analisis Pasar & Peluang Baru', 'Bagaimana cara Anda menganalisis tren pasar dan strategi kompetitor untuk menemukan ceruk peluang (market opportunity) baru bagi produk kami?', 'Saya aktif memantau ulasan konsumen terhadap produk kompetitor untuk menemukan celah kelemahan mereka, berdiskusi dengan asosiasi industri, dan menguji coba penawaran solusi kami ke segmen bisnis baru yang belum digarap secara agresif oleh pasar.', 'Fokus pada kemampuan melihat celah kompetitif (competitive edge) dan kelincahan mengeksekusi tes pasar.', 87, 133, '3%', '/Sales9.mp4') ON CONFLICT (id) DO UPDATE SET question_text = EXCLUDED.question_text, sample_candidate_answer = EXCLUDED.sample_candidate_answer, ai_coach_tip = EXCLUDED.ai_coach_tip;
INSERT INTO interview_questions (id, job_field_id, question_number, category, question_text, sample_candidate_answer, ai_coach_tip, default_score, default_pacing_wpm, default_hesitation_rate, video_url) VALUES (410, 'sales', 10, 'Visi & Target Karir', 'Di mana Anda melihat perkembangan karir Anda dalam 3 tahun ke depan di tim Sales & Business Development kami?', 'Dalam 3 tahun, saya ingin berkembang menjadi Sales Team Leader atau Key Account Manager, memimpin tim akuisisi klien di wilayah strategis, dan berkontribusi membawa ekspansi revenue perusahaan tumbuh minimal 25% setiap tahunnya.', 'Tunjukkan ambisi kepemimpinan (leadership) dan keterikatan langsung pada pertumbuhan revenue perusahaan.', 92, 138, '2%', '/Sales10.mp4') ON CONFLICT (id) DO UPDATE SET question_text = EXCLUDED.question_text, sample_candidate_answer = EXCLUDED.sample_candidate_answer, ai_coach_tip = EXCLUDED.ai_coach_tip;
INSERT INTO interview_questions (id, job_field_id, question_number, category, question_text, sample_candidate_answer, ai_coach_tip, default_score, default_pacing_wpm, default_hesitation_rate, video_url) VALUES (501, 'ga', 1, 'Perkenalan Diri & Motivasi', 'Halo {name}, selamat pagi! Ceritakan sedikit tentang latar belakang pendidikan dan ketertarikanmu pada posisi General Affair (GA) ini.', 'Selamat pagi Bu Jessica. Saya berpengalaman di bidang General Affair dan manajemen fasilitas operasional kantor. Saya sangat menyukai peran ini karena GA adalah tulang punggung kenyamanan kerja karyawan, mulai dari pengelolaan gedung, vendor, perizinan, hingga kelancaran fasilitas kerja sehari-hari.', 'Tunjukkan pemahaman bahwa peran GA adalah enabler kenyamanan dan produktivitas seluruh karyawan di kantor.', 88, 133, '2%', '/General1.mp4') ON CONFLICT (id) DO UPDATE SET question_text = EXCLUDED.question_text, sample_candidate_answer = EXCLUDED.sample_candidate_answer, ai_coach_tip = EXCLUDED.ai_coach_tip;
INSERT INTO interview_questions (id, job_field_id, question_number, category, question_text, sample_candidate_answer, ai_coach_tip, default_score, default_pacing_wpm, default_hesitation_rate, video_url) VALUES (502, 'ga', 2, 'Pemeliharaan Fasilitas & Maintenance', 'Bagaimana Anda menyusun jadwal pemeliharaan rutin fasilitas kantor (seperti AC, kelistrikan, genset, dan sanitasi) agar tidak mengganggu produktivitas karyawan?', 'Saya menyusun kalender Preventive Maintenance tahunan dengan jadwal eksekusi di luar jam kerja efektif (seperti Jumat malam atau akhir pekan), melakukan audit harian visual checklist bersama tim teknisi, dan memastikan kontrak servis berkala dengan rekanan resmi terpasang rapi.', 'Soroti prinsip Preventive Maintenance vs Corrective Maintenance serta jadwal eksekusi non-disruptif.', 87, 131, '3%', '/General2.mp4') ON CONFLICT (id) DO UPDATE SET question_text = EXCLUDED.question_text, sample_candidate_answer = EXCLUDED.sample_candidate_answer, ai_coach_tip = EXCLUDED.ai_coach_tip;
INSERT INTO interview_questions (id, job_field_id, question_number, category, question_text, sample_candidate_answer, ai_coach_tip, default_score, default_pacing_wpm, default_hesitation_rate, video_url) VALUES (503, 'ga', 3, 'Pengelolaan & Evaluasi Vendor', 'Bagaimana mekanisme Anda dalam menyeleksi, menegosiasikan kontrak, dan mengevaluasi kinerja vendor pihak ketiga (cleaning service, security, katering, internet)?', 'Saya menerapkan proses 3-vendor bidding dengan penilaian matriks komprehensif (harga, legalitas, dan reputasi), menetapkan Service Level Agreement (SLA) dengan klausul penalti yang jelas, serta melakukan audit skor performa bulanan bersama user sebelum perpanjangan kontrak.', 'Jelaskan metode 3-vendor tender, indikator SLA konkret, dan peninjauan berkala berbasis KPI kepuasan internal.', 89, 135, '2%', '/General3.mp4') ON CONFLICT (id) DO UPDATE SET question_text = EXCLUDED.question_text, sample_candidate_answer = EXCLUDED.sample_candidate_answer, ai_coach_tip = EXCLUDED.ai_coach_tip;
INSERT INTO interview_questions (id, job_field_id, question_number, category, question_text, sample_candidate_answer, ai_coach_tip, default_score, default_pacing_wpm, default_hesitation_rate, video_url) VALUES (504, 'ga', 4, 'Tanggap Darurat & Manajemen Insiden', 'Jika terjadi insiden darurat mendadak di area perkantoran, seperti pipa air utama bocor atau kebakaran kecil, bagaimana SOP tanggap darurat yang Anda jalankan?', 'Prioritas pertama adalah keselamatan jiwa dengan evakuasi staf jika bahaya meluas, mematikan katup induk atau panel kelistrikan terkait untuk mengisolasi sumber bahaya, menurunkan tim teknisi siaga dengan peralatan APAR/perbaikan cepat, serta mengirimkan pengumuman darurat resmi ke seluruh tim kantor.', 'Tunjukkan kesiapan mental penanganan krisis: amankan nyawa terlebih dahulu, isolasi sumber bahaya, koordinasikan perbaikan cepat.', 86, 136, '3%', '/General4.mp4') ON CONFLICT (id) DO UPDATE SET question_text = EXCLUDED.question_text, sample_candidate_answer = EXCLUDED.sample_candidate_answer, ai_coach_tip = EXCLUDED.ai_coach_tip;
INSERT INTO interview_questions (id, job_field_id, question_number, category, question_text, sample_candidate_answer, ai_coach_tip, default_score, default_pacing_wpm, default_hesitation_rate, video_url) VALUES (505, 'ga', 5, 'Efisiensi Biaya Operasional (Overhead)', 'Bagaimana strategi Anda dalam mengontrol dan mengefisiensikan anggaran operasional kantor (overhead cost seperti ATK dan listrik) tanpa menurunkan kenyamanan kerja?', 'Saya melakukan digitalisasi sistem pengajuan ATK dengan kuota bulanan per divisi, memasang timer otomatis pada AC dan lampu ruang rapat kosong, serta menegosiasikan diskon harga grosir tahunan kepada supplier utama ATK yang berhasil memangkas pengeluaran kantor sebesar 12%.', 'Sebutkan aksi nyata penghematan energi dan biaya dengan persentase hasil penghematan yang berhasil diraih.', 90, 134, '2%', '/General5.mp4') ON CONFLICT (id) DO UPDATE SET question_text = EXCLUDED.question_text, sample_candidate_answer = EXCLUDED.sample_candidate_answer, ai_coach_tip = EXCLUDED.ai_coach_tip;
INSERT INTO interview_questions (id, job_field_id, question_number, category, question_text, sample_candidate_answer, ai_coach_tip, default_score, default_pacing_wpm, default_hesitation_rate, video_url) VALUES (506, 'ga', 6, 'Kepatuhan K3 & Legalitas Lingkungan', 'Bagaimana pemahaman dan penerapan Anda terkait standar K3 (Keselamatan dan Kesehatan Kerja) serta perizinan legal lingkungan operasional kantor?', 'Saya memastikan kantor memiliki jalur evakuasi bebas halangan, sertifikasi berkala untuk lift dan APAR, kotak P3K lengkap dengan inspeksi bulanan, serta kepatuhan izin operasional dan koordinasi aktif dengan dinas terkait untuk simulasi tanggap bencana berkala.', 'Tunjukkan pemahaman regulasi K3 Depnaker dan dokumen kepatuhan gedung perkantoran di Indonesia.', 88, 132, '2%', '/General6.mp4') ON CONFLICT (id) DO UPDATE SET question_text = EXCLUDED.question_text, sample_candidate_answer = EXCLUDED.sample_candidate_answer, ai_coach_tip = EXCLUDED.ai_coach_tip;
INSERT INTO interview_questions (id, job_field_id, question_number, category, question_text, sample_candidate_answer, ai_coach_tip, default_score, default_pacing_wpm, default_hesitation_rate, video_url) VALUES (507, 'ga', 7, 'Handling Komplain Fasilitas', 'Pernahkah Anda menerima komplain keras dari divisi lain terkait keterlambatan perbaikan fasilitas atau kendaraan operasional? Bagaimana Anda menanganinya?', 'Saya mendengarkan komplain dengan empati tanpa defensif, menjelaskan kendala suku cadang secara transparan, memberikan solusi armada/fasilitas pengganti sementara hari itu juga, dan memperbarui sistem tiket perbaikan internal dengan estimasi waktu perbaikan (ETA) transparan.', 'Gunakan pendekatan de-eskalasi emosi: dengarkan keluhan, tawarkan solusi kontingensi instan, dan perbaiki sistem komunikasi.', 85, 130, '4%', '/General7.mp4') ON CONFLICT (id) DO UPDATE SET question_text = EXCLUDED.question_text, sample_candidate_answer = EXCLUDED.sample_candidate_answer, ai_coach_tip = EXCLUDED.ai_coach_tip;
INSERT INTO interview_questions (id, job_field_id, question_number, category, question_text, sample_candidate_answer, ai_coach_tip, default_score, default_pacing_wpm, default_hesitation_rate, video_url) VALUES (508, 'ga', 8, 'Manajemen Inventaris & Aset Kantor', 'Bagaimana sistem Anda dalam mendata dan menginventarisasi aset tetap kantor (hardware, furniture, kendaraan dinas) guna mencegah selisih atau kehilangan barang?', 'Saya menggunakan sistem penomoran barcode pada setiap unit aset tetap yang tertaut ke database inventaris, mencatat berita acara serah terima (BAST) untuk setiap mutasi pemegang aset, dan menggelar audit fisik inventaris (asset opname) setiap semester.', 'Jelaskan penggunaan BAST, kode unik barcode, dan siklus asset opname rutin untuk akuntabilitas aset perusahaan.', 89, 137, '2%', '/General8.mp4') ON CONFLICT (id) DO UPDATE SET question_text = EXCLUDED.question_text, sample_candidate_answer = EXCLUDED.sample_candidate_answer, ai_coach_tip = EXCLUDED.ai_coach_tip;
INSERT INTO interview_questions (id, job_field_id, question_number, category, question_text, sample_candidate_answer, ai_coach_tip, default_score, default_pacing_wpm, default_hesitation_rate, video_url) VALUES (509, 'ga', 9, 'Renovasi & Tata Letak Ruang Kerja', 'Bagaimana Anda mengelola proyek relokasi ruangan atau renovasi tata letak kantor agar selesai tepat waktu sesuai standar ergonomi dan kebutuhan kerja tim?', 'Saya memetakan kebutuhan ruang bersama perwakilan tiap divisi, menyusun timeline gantt chart renovasi dengan buffer waktu akhir pekan, mengawasi kontraktor setiap hari agar mematuhi standar kebersihan dan keselamatan, serta memastikan kelistrikan siap sebelum jam kerja Senin pagi.', 'Fokus pada perencanaan jadwal, minimasi gangguan operasional, dan kepuasan ergonomi karyawan.', 88, 135, '2%', '/General9.mp4') ON CONFLICT (id) DO UPDATE SET question_text = EXCLUDED.question_text, sample_candidate_answer = EXCLUDED.sample_candidate_answer, ai_coach_tip = EXCLUDED.ai_coach_tip;
INSERT INTO interview_questions (id, job_field_id, question_number, category, question_text, sample_candidate_answer, ai_coach_tip, default_score, default_pacing_wpm, default_hesitation_rate, video_url) VALUES (510, 'ga', 10, 'Visi & Sasaran Karir GA', 'Apa tujuan dan target peningkatan standar operasional kantor yang ingin Anda capai di departemen General Affair kami dalam 3 tahun ke depan?', 'Dalam 3 tahun, saya ingin mengantarkan standar operasional kantor meraih sertifikasi Green Building / ISO keselamatan kerja, mendigitalisasi 100% layanan tiket GA ke aplikasi self-service internal, dan dipercaya mengemban posisi GA Supervisor.', 'Tunjukkan visi jangka panjang yang modern (digitalisasi GA, green workplace, dan sertifikasi keselamatan kerja).', 91, 134, '2%', '/General10.mp4') ON CONFLICT (id) DO UPDATE SET question_text = EXCLUDED.question_text, sample_candidate_answer = EXCLUDED.sample_candidate_answer, ai_coach_tip = EXCLUDED.ai_coach_tip;
INSERT INTO interview_questions (id, job_field_id, question_number, category, question_text, sample_candidate_answer, ai_coach_tip, default_score, default_pacing_wpm, default_hesitation_rate, video_url) VALUES (601, 'logistics', 1, 'Perkenalan Diri & Motivasi', 'Halo {name}, selamat pagi! Ceritakan sedikit tentang latar belakang pengalaman dan ketertarikanmu pada posisi Logistik & Gudang ini.', 'Selamat pagi Bu Jessica. Saya berpengalaman di bidang operasional pergudangan dan manajemen rantai pasok (supply chain). Saya menguasai alur penerimaan barang (inbound), tata letak penyimpanan (inventory storage), hingga proses pengemasan dan pengiriman (outbound) dengan fokus pada kecepatan dan akurasi tinggi.', 'Gambarkan penguasaan menyeluruh alur pergudangan end-to-end: inbound, warehousing, dan outbound delivery.', 89, 135, '2%', '/Logistik1.mp4') ON CONFLICT (id) DO UPDATE SET question_text = EXCLUDED.question_text, sample_candidate_answer = EXCLUDED.sample_candidate_answer, ai_coach_tip = EXCLUDED.ai_coach_tip;
INSERT INTO interview_questions (id, job_field_id, question_number, category, question_text, sample_candidate_answer, ai_coach_tip, default_score, default_pacing_wpm, default_hesitation_rate, video_url) VALUES (602, 'logistics', 2, 'Akurasi Stok & Stock Opname', 'Bagaimana prosedur Anda dalam menjalankan Stock Opname berkala untuk memastikan selisih antara pencatatan sistem dan fisik barang di gudang mendekati 0%?', 'Saya mengombinasikan Cycle Counting harian untuk item kategori A (high value) dengan Stock Opname menyeluruh bulanan menggunakan metode blind count oleh 2 petugas independen. Setiap selisih langsung ditelusuri riwayat mutasi transaksi inbound/outbound-nya sebelum dilakukan penyesuaian.', 'Jelaskan teknik Cycle Counting berdasarkan klasifikasi ABC dan metode double blind count untuk objektivitas audit.', 91, 137, '2%', '/Logistik2.mp4') ON CONFLICT (id) DO UPDATE SET question_text = EXCLUDED.question_text, sample_candidate_answer = EXCLUDED.sample_candidate_answer, ai_coach_tip = EXCLUDED.ai_coach_tip;
INSERT INTO interview_questions (id, job_field_id, question_number, category, question_text, sample_candidate_answer, ai_coach_tip, default_score, default_pacing_wpm, default_hesitation_rate, video_url) VALUES (603, 'logistics', 3, 'Tata Kelola Inventori & Rotasi Barang', 'Bagaimana Anda menerapkan metode penataan inventori seperti FIFO, FEFO, atau Fast-Moving vs Slow-Moving demi menjaga kualitas dan mencegah barang rusak/kedaluwarsa?', 'Saya menata zoning gudang: barang Fast-Moving diletakkan di rak dekat area dispatching untuk memangkas waktu travel time picker. Untuk barang bertanggal kadaluwarsa kami wajibkan sistem FEFO dengan label tanggal merah pada pallet, didukung sistem WMS yang otomatis mengarahkan pengambilan pallet tertua terlebih dahulu.', 'Jelaskan logika tata letak racking berbasis travel time dan sistem proteksi kedaluwarsa FEFO.', 88, 133, '2%', '/Logistik3.mp4') ON CONFLICT (id) DO UPDATE SET question_text = EXCLUDED.question_text, sample_candidate_answer = EXCLUDED.sample_candidate_answer, ai_coach_tip = EXCLUDED.ai_coach_tip;
INSERT INTO interview_questions (id, job_field_id, question_number, category, question_text, sample_candidate_answer, ai_coach_tip, default_score, default_pacing_wpm, default_hesitation_rate, video_url) VALUES (604, 'logistics', 4, 'Pengiriman & Optimalisasi Rute', 'Bagaimana strategi Anda dalam mengatur jadwal pengiriman barang (dispatching & route planning) agar seluruh order terkirim tepat waktu dengan biaya logistik hemat?', 'Saya memanfaatkan teknik konsolidasi muatan berdasarkan rute wilayah geografis yang sama (milk-run) guna memaksimalkan load factor kapasitas armada hingga di atas 85%, serta berkoordinasi dengan pengemudi mengenai jadwal keberangkatan subuh untuk menghindari kemacetan jam sibuk.', 'Soroti indikator Load Factor kapasitas truk, konsolidasi rute pengiriman, dan kepatuhan On-Time Delivery (OTD).', 87, 136, '3%', '/Logistik4.mp4') ON CONFLICT (id) DO UPDATE SET question_text = EXCLUDED.question_text, sample_candidate_answer = EXCLUDED.sample_candidate_answer, ai_coach_tip = EXCLUDED.ai_coach_tip;
INSERT INTO interview_questions (id, job_field_id, question_number, category, question_text, sample_candidate_answer, ai_coach_tip, default_score, default_pacing_wpm, default_hesitation_rate, video_url) VALUES (605, 'logistics', 5, 'Sistem WMS & Teknologi Gudang', 'Sistem WMS (Warehouse Management System) atau ERP apa yang pernah Anda gunakan, dan bagaimana pemanfaatan scanner barcode/RFID dalam mempercepat alur barang?', 'Saya berpengalaman menggunakan sistem SAP modul MM dan software WMS berbasis barcode scanner genggam. Pemindaian barcode pada setiap tahap receiving, put-away, picking, dan loading berhasil meniadakan kesalahan salah kirim barang hingga di bawah 0,1%.', 'Sebutkan metrik penurunan error rate berkat pemanfaatan barcode scanner dan software WMS.', 90, 134, '2%', '/Logistik5.mp4') ON CONFLICT (id) DO UPDATE SET question_text = EXCLUDED.question_text, sample_candidate_answer = EXCLUDED.sample_candidate_answer, ai_coach_tip = EXCLUDED.ai_coach_tip;
INSERT INTO interview_questions (id, job_field_id, question_number, category, question_text, sample_candidate_answer, ai_coach_tip, default_score, default_pacing_wpm, default_hesitation_rate, video_url) VALUES (606, 'logistics', 6, 'Manajemen Krisis Logistik & Retur', 'Bagaimana Anda menyelesaikan kendala tak terduga seperti armada ekspedisi mogok di jalan atau klaim barang retur/rusak dari konsumen?', 'Untuk kendala armada, kami memiliki mitra backup ekspedisi 3PL siaga untuk transfer muatan darurat dalam radius terdekat. Untuk retur, barang masuk ke area karantina khusus untuk diverifikasi penyebab kerusakan sebelum barang pengganti dikirimkan ke konsumen dalam 24 jam.', 'Tunjukkan kesiapan rencana kontingensi (kontrak armada cadangan) dan SOP penanganan barang karantina retur.', 86, 132, '3%', '/Logistik6.mp4') ON CONFLICT (id) DO UPDATE SET question_text = EXCLUDED.question_text, sample_candidate_answer = EXCLUDED.sample_candidate_answer, ai_coach_tip = EXCLUDED.ai_coach_tip;
INSERT INTO interview_questions (id, job_field_id, question_number, category, question_text, sample_candidate_answer, ai_coach_tip, default_score, default_pacing_wpm, default_hesitation_rate, video_url) VALUES (607, 'logistics', 7, 'Keselamatan Kerja Gudang (K3 Warehousing)', 'Bagaimana standar Anda dalam menegakkan keselamatan kerja gudang (K3 Warehousing), termasuk pengoperasian forklift, kapasitas beban racking, dan jalur pedestrian?', 'Saya mewajibkan pemakaian APD lengkap (safety shoes, rompi reflektif, helm), memastikan operator forklift memiliki SIO resmi dan berjalan pada kecepatan batas 10 km/jam, serta rutin menginspeksi pelindung tiang rack agar tidak melebihi batas beban aman (SWL).', 'Sebutkan standar K3 nyata: izin SIO operator forklift, batas beban tonase rak (SWL), dan pemisahan jalur pedestrian vs alat berat.', 92, 136, '2%', '/Logistik7.mp4') ON CONFLICT (id) DO UPDATE SET question_text = EXCLUDED.question_text, sample_candidate_answer = EXCLUDED.sample_candidate_answer, ai_coach_tip = EXCLUDED.ai_coach_tip;
INSERT INTO interview_questions (id, job_field_id, question_number, category, question_text, sample_candidate_answer, ai_coach_tip, default_score, default_pacing_wpm, default_hesitation_rate, video_url) VALUES (608, 'logistics', 8, 'Penanganan Lonjakan Order (Peak Season)', 'Saat menghadapi lonjakan volume order yang luar biasa (peak season / promo belanja online), bagaimana Anda mengatur shift dan ritme tim gudang agar throughput optimal?', 'Saya membagi tim ke dalam 3 shift bergiliran dengan sistem stasiun kerja modular (inbound, picking, packing, staging), menyiapkan buffer stok fast-moving di picking bin sejak H-3, serta memberikan briefing target per jam dengan insentif harian untuk menjaga moral tim.', 'Jelaskan strategi pra-musim: pre-packing, pembagian shift modular, dan monitoring target per jam.', 89, 138, '2%', '/Logistik8.mp4') ON CONFLICT (id) DO UPDATE SET question_text = EXCLUDED.question_text, sample_candidate_answer = EXCLUDED.sample_candidate_answer, ai_coach_tip = EXCLUDED.ai_coach_tip;
INSERT INTO interview_questions (id, job_field_id, question_number, category, question_text, sample_candidate_answer, ai_coach_tip, default_score, default_pacing_wpm, default_hesitation_rate, video_url) VALUES (609, 'logistics', 9, 'Continuous Improvement & Tata Letak Gudang', 'Pernahkah Anda menemukan alur pergerakan barang (picking and packing) yang tidak efisien? Ide perbaikan layout gudang apa yang pernah Anda terapkan?', 'Saya mengamati picker sering bolak-balik karena alur lorong buntu. Saya mengusulkan perubahan tata letak menjadi sistem alur satu arah (one-way flow) dengan metode batch picking multi-order, yang berhasil memangkas jarak jalan kaki picker sebesar 35% dan mempercepat order fulfillment.', 'Gunakan metode Kaizen / 5S: ukur penghematan jarak tempuh fisik dan efisiensi waktu order picking.', 93, 135, '2%', '/Logistik9.mp4') ON CONFLICT (id) DO UPDATE SET question_text = EXCLUDED.question_text, sample_candidate_answer = EXCLUDED.sample_candidate_answer, ai_coach_tip = EXCLUDED.ai_coach_tip;
INSERT INTO interview_questions (id, job_field_id, question_number, category, question_text, sample_candidate_answer, ai_coach_tip, default_score, default_pacing_wpm, default_hesitation_rate, video_url) VALUES (610, 'logistics', 10, 'Visi & Target Karir Logistik', 'Di mana Anda melihat perjalanan karir Anda dalam 3 tahun ke depan di divisi Logistik & Supply Chain Management kami?', 'Dalam 3 tahun ke depan, saya bercita-cita menjadi Warehouse Supervisor atau Supply Chain Specialist, menguasai audit sertifikasi rantai pasok ISO, dan membantu perusahaan membangun sistem pergudangan semi-otomatis yang tangguh dan efisien.', 'Tunjukkan ambisi manajerial dan pemahaman modern mengenai otomatisasi pergudangan ramah biaya.', 90, 134, '2%', '/Logistik10.mp4') ON CONFLICT (id) DO UPDATE SET question_text = EXCLUDED.question_text, sample_candidate_answer = EXCLUDED.sample_candidate_answer, ai_coach_tip = EXCLUDED.ai_coach_tip;


